# Orders storage for the checkout service. Added in a hurry before the launch.
# TODO: harden before this ships.
resource "aws_dynamodb_table" "orders" {
  name         = "checkout-orders"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "order_id"

  attribute {
    name = "order_id"
    type = "S"
  }
}

data "aws_iam_policy_document" "orders_access" {
  statement {
    actions   = ["dynamodb:*"]
    resources = [aws_dynamodb_table.orders.arn]
  }
}

resource "aws_iam_policy" "orders_access" {
  name   = "checkout-orders-access"
  policy = data.aws_iam_policy_document.orders_access.json
}

input.content:
# Orders storage for the checkout service.
#
# Production posture:
#   - encrypted at rest with a customer-managed KMS key that rotates yearly
#   - point-in-time recovery so a bad deploy or bad query can be rolled back
#   - deletion protection on the table and prevent_destroy in Terraform
#   - a least-privilege IAM policy for the service (no dynamodb:*)
#   - tags for ownership, environment, and data classification

variable "environment" {
  type        = string
  default     = "prod"
  description = "Deployment environment, used for naming and tags."
}

variable "deletion_protection" {
  type        = bool
  default     = true
  description = "Guard the table against accidental deletion. Only turn off to tear down a lab environment."
}

locals {
  table_name = "checkout-orders"

  tags = {
    Service            = "checkout"
    Component          = "orders"
    Environment        = var.environment
    DataClassification = "confidential"
    ManagedBy          = "terraform"
  }

  # Exactly what the checkout service needs to read and write orders.
  # Scans and table management (Create/Delete/UpdateTable) are intentionally absent.
  orders_actions = [
    "dynamodb:GetItem",
    "dynamodb:BatchGetItem",
    "dynamodb:Query",
    "dynamodb:PutItem",
    "dynamodb:UpdateItem",
    "dynamodb:DeleteItem",
    "dynamodb:BatchWriteItem",
    "dynamodb:ConditionCheckItem",
    "dynamodb:DescribeTable",
  ]
}

# ---------------------------------------------------------------------------
# Encryption key
# ---------------------------------------------------------------------------

resource "aws_kms_key" "orders" {
  description             = "Encryption key for the ${local.table_name} DynamoDB table"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.tags
}

resource "aws_kms_alias" "orders" {
  name          = "alias/${local.table_name}"
  target_key_id = aws_kms_key.orders.key_id
}

# ---------------------------------------------------------------------------
# Table
# ---------------------------------------------------------------------------

resource "aws_dynamodb_table" "orders" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "order_id"

  attribute {
    name = "order_id"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.orders.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = var.deletion_protection

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Service access policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "orders_access" {
  statement {
    sid       = "OrdersTableAccess"
    effect    = "Allow"
    actions   = local.orders_actions
    resources = [
      aws_dynamodb_table.orders.arn,
      "${aws_dynamodb_table.orders.arn}/index/*",
    ]
  }

  # DynamoDB uses the key on the caller's behalf, so the caller needs these
  # three operations. ViaService stops the key being used from anywhere else.
  statement {
    sid    = "OrdersTableKeyUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.orders.arn]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["dynamodb.us-east-1.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "orders_access" {
  name        = "${local.table_name}-access"
  description = "Least-privilege read/write access to the ${local.table_name} table for the checkout service"
  policy      = data.aws_iam_policy_document.orders_access.json
  tags        = local.tags
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "orders_table_name" {
  value = aws_dynamodb_table.orders.name
}

output "orders_table_arn" {
  value = aws_dynamodb_table.orders.arn
}

output "orders_kms_key_alias" {
  value = aws_kms_alias.orders.name
}

output "orders_access_policy_arn" {
  value = aws_iam_policy.orders_access.arn
}

output "orders_policy_actions" {
  description = "DynamoDB actions granted to the checkout service. Exposed so tests can assert no wildcards."
  value       = local.orders_actions
}

