input.content:
# Production-readiness checks for the checkout orders table.
# Runs against the plan only, so no LocalStack or AWS account is needed.

run "orders_table_is_hardened" {
  command = plan

  assert {
    condition     = aws_dynamodb_table.orders.point_in_time_recovery[0].enabled == true
    error_message = "Point-in-time recovery must be enabled on the orders table."
  }

  assert {
    condition     = aws_dynamodb_table.orders.server_side_encryption[0].enabled == true
    error_message = "Server-side encryption must be enabled on the orders table."
  }

  assert {
    condition     = aws_dynamodb_table.orders.deletion_protection_enabled == true
    error_message = "Deletion protection must be enabled on the orders table by default."
  }

  assert {
    condition     = aws_kms_key.orders.enable_key_rotation == true
    error_message = "The orders table KMS key must have automatic rotation enabled."
  }

  assert {
    condition     = aws_dynamodb_table.orders.tags["DataClassification"] == "confidential"
    error_message = "The orders table must be tagged with its data classification."
  }
}

run "orders_policy_is_least_privilege" {
  command = plan

  assert {
    condition     = !contains(output.orders_policy_actions, "dynamodb:*")
    error_message = "The orders access policy must not grant dynamodb:*."
  }

  assert {
    condition     = length([for a in output.orders_policy_actions : a if endswith(a, "*")]) == 0
    error_message = "The orders access policy must not contain wildcard actions."
  }

  assert {
    condition     = !contains(output.orders_policy_actions, "dynamodb:Scan")
    error_message = "The checkout service must not be able to scan the orders table."
  }

  assert {
    condition = length(setintersection(toset(output.orders_policy_actions), toset([
      "dynamodb:DeleteTable",
      "dynamodb:CreateTable",
      "dynamodb:UpdateTable",
      "dynamodb:UpdateContinuousBackups",
    ]))) == 0
    error_message = "The checkout service must not be able to manage or weaken the orders table."
  }
}

